const promptRow = $input.first().json[0];
const trigger = $('Capture Start').first().json;
if (!promptRow) {
  throw new Error(`No active prompt found for prompt_key: ${trigger.prompt_key}`);
}
const variables = trigger.variables || {};
function fill(template, vars) {
  return template.replace(/\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g, (match, key) => vars[key] !== undefined ? String(vars[key]) : '');
}
return [{
  json: {
    system_prompt: promptRow.system_prompt,
    user_message: fill(promptRow.user_prompt_template, variables),
    prompt_key: promptRow.prompt_key,
    prompt_version: promptRow.version,
    model: trigger.model || 'claude-opus-4-8',
    max_tokens: trigger.max_tokens || 2048,
    enable_web_search: !!trigger.enable_web_search,
    image_data: trigger.image_data || null,
    image_media_type: trigger.image_media_type || 'image/jpeg'
  }
}];

const response = $input.first().json;

if (response.stop_reason === 'refusal') {
  throw new Error('Claude refused the request: ' + (response.stop_details?.explanation || 'no explanation provided'));
}

const textBlocks = (response.content || []).filter(b => b.type === 'text');
if (textBlocks.length === 0) {
  throw new Error('Claude response contained no text content.');
}

// Concatenate rather than take the first block - when web search is enabled (Phase 7, Research Agent) Claude can interleave multiple text blocks with search results in one response.
let output = textBlocks.map(b => b.text).join('\n\n');
let parsed = null;
try {
  parsed = JSON.parse(output);
} catch (e) {
  // Not every prompt expects JSON (daily_briefing, knowledge_search are prose) - that's fine.
}

return [{
  json: {
    output: parsed ?? output,
    is_structured: parsed !== null,
    raw_text: output,
    model: response.model,
    input_tokens: response.usage?.input_tokens ?? null,
    output_tokens: response.usage?.output_tokens ?? null
  }
}];

const trigger = $('Capture Start').first().json;
return [{
  json: {
    user_id: trigger.user_id,
    workflow_name: 'AI - Process Request',
    status: 'success',
    started_at: trigger.started_at,
    related_record_type: trigger.related_record_type || null,
    related_record_id: trigger.related_record_id || null
  }
}];

const validated = $('Validate & Parse Response').first().json;
const filled = $('Fill Template').first().json;
return [{
  json: {
    success: true,
    output: validated.output,
    is_structured: validated.is_structured,
    prompt_key: filled.prompt_key,
    prompt_version: filled.prompt_version,
    usage: { input_tokens: validated.input_tokens, output_tokens: validated.output_tokens, model: validated.model }
  }
}];
